import { Supplier, getAllSuppliers, createSupplier, updateSupplier, deleteSupplier } from '../api/supplierApi';
import { InputInputEventDetail, ToggleChangeEventDetail, CustomEvent } from '@ionic/core';

const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

const SupplierPage: React.FC = () => {
  const { companyId } = useUser();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentSupplier, setCurrentSupplier] = useState<Partial<Supplier> | null>(null);
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [supplierToDelete, setSupplierToDelete] = useState<number | null>(null);
  const [saving, setSaving] = useState(false);
  const [searchText, setSearchText] = useState('');
  const [displayCount, setDisplayCount] = useState(20);

  const [popoverState, setPopoverState] = useState({
    showAlertPopover: false,
    showMailPopover: false,
    event: undefined as Event | undefined,
  });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const fetchSuppliers = async () => {
    if (!companyId) {
      setError('Company ID is not available.');
      return;
    }
    setLoading(true);
    try {
      const data = await getAllSuppliers(companyId);
      setSuppliers(data);
      setDisplayCount(20); // Reset display count on new fetch
    } catch (err) {
      setError((err as Error).message ?? 'Error loading suppliers');
    }
    setLoading(false);
  };

  useIonViewWillEnter(() => {
    fetchSuppliers();
  }, [companyId]);

  const handleSaveSupplier = async () => {
    if (!currentSupplier || !companyId || !currentSupplier.supplierName) {
      setError('Supplier name and Company ID are required.');
      return;
    }
    setSaving(true);
    try {
      const payload = { ...currentSupplier, companyId, active: currentSupplier.active === '1' ? '1' : '0' };
      if (isEditing && currentSupplier.supplierId) {
        await updateSupplier(currentSupplier.supplierId, payload);
      } else {
        await createSupplier(payload);
      }
      fetchSuppliers();
      setShowModal(false);
    } catch (err) {
      setError((err as Error).message ?? 'Error saving supplier');
    }
    setSaving(false);
  };

  const handleDeleteSupplier = async () => {
    if (supplierToDelete === null || !companyId) return;
    setLoading(true);
    try {
      await deleteSupplier(supplierToDelete, companyId);
      fetchSuppliers();
    } catch (err) {
      setError((err as Error).message ?? 'Error deleting supplier');
    }
    setLoading(false);
    setSupplierToDelete(null);
  };

  const openCreateModal = () => {
    setIsEditing(false);
    setCurrentSupplier({ supplierName: '', contactName: '', phone: '', email: '', address: '', active: '1' });
    setShowModal(true);
  };

  const openEditModal = (supplier: Supplier) => {
    setIsEditing(true);
    setCurrentSupplier({ ...supplier });
    setShowModal(true);
  };

  const confirmDelete = (id: number) => {
    setSupplierToDelete(id);
    setShowDeleteAlert(true);
  };

  const filteredSuppliers = suppliers.filter(s =>
    s.supplierName.toLowerCase().includes(searchText.toLowerCase())
  );

  const loadMoreItems = () => {
    setTimeout(() => {
      setDisplayCount(prevCount => prevCount + 20);
    }, 500);
  };

  return (
    <IonPage className="supplier-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Proveedores — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonLoading isOpen={loading} message="Cargando proveedores..." />
        <IonToast isOpen={!!error} message={error} onDidDismiss={() => setError('')} duration={3000} color="danger" />

        <div className="supplier-search-bar">
          <IonInput
            fill="outline"
            label="Buscar proveedor"
            labelPlacement="floating"
            value={searchText}
            onIonInput={(e: CustomEvent<InputInputEventDetail>) => setSearchText(e.detail.value!)}
            clearInput
          >
            <IonIcon icon={peopleOutline} slot="start" />
          </IonInput>
        </div>

        <IonList className="supplier-list">
          {filteredSuppliers.slice(0, displayCount).map(supplier => (
            <IonItem key={supplier.supplierId} className="supplier-item ion-activatable">
              <IonLabel>
                <h2>{supplier.supplierName}</h2>
                <p>{supplier.contactName} - {supplier.phone}</p>
                <p>Email: {supplier.email}</p>
                <p>Dirección: {supplier.address}</p>
                <p>Activo: {supplier.active === '1' ? 'Sí' : 'No'}</p>
                <p>Creado: {toHermosillo(supplier.created_At)}</p>
                {supplier.updated_at && <p>Actualizado: {toHermosillo(supplier.updated_at)}</p>}
              </IonLabel>
              <IonButton fill="clear" slot="end" onClick={() => openEditModal(supplier)}>
                <IonIcon icon={createOutline} />
              </IonButton>
              <IonButton fill="clear" color="danger" slot="end" onClick={() => confirmDelete(supplier.supplierId)}>
                <IonIcon icon={trashOutline} />
              </IonButton>
            </IonItem>
          ))}
          <IonInfiniteScroll onIonInfinite={(ev: CustomEvent<void>) => {
            loadMoreItems();
            (ev.target as HTMLIonInfiniteScrollElement).complete();
          }} threshold="100px" disabled={displayCount >= filteredSuppliers.length}>
            <IonInfiniteScrollContent loadingText="Cargando más proveedores..."></IonInfiniteScrollContent>
          </IonInfiniteScroll>
        </IonList>

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={openCreateModal}>
            <IonIcon icon={addOutline} />
          </IonFabButton>
        </IonFab>

        <IonModal isOpen={showModal} onDidDismiss={() => setShowModal(false)} className="supplier-modal">
          <IonHeader>
            <IonToolbar>
              <IonTitle>{isEditing ? 'Editar Proveedor' : 'Crear Proveedor'}</IonTitle>
              <IonButton slot="end" fill="clear" onClick={() => setShowModal(false)}>
                <IonIcon icon={closeOutline} />
              </IonButton>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            <div className="modal-form-fields">
              <IonInput
                fill="outline"
                label="Nombre del Proveedor *"
                labelPlacement="floating"
                value={currentSupplier?.supplierName}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => setCurrentSupplier(p => ({ ...p, supplierName: e.detail.value! }))}
                className={!currentSupplier?.supplierName ? 'ion-invalid ion-touched' : ''}
                errorText={!currentSupplier?.supplierName ? 'El nombre del proveedor es obligatorio' : ''}
              />
              <IonInput
                fill="outline"
                label="Nombre de Contacto"
                labelPlacement="floating"
                value={currentSupplier?.contactName}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => setCurrentSupplier(p => ({ ...p, contactName: e.detail.value! }))}
              />
              <IonInput
                fill="outline"
                label="Teléfono"
                labelPlacement="floating"
                type="tel"
                value={currentSupplier?.phone}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => setCurrentSupplier(p => ({ ...p, phone: e.detail.value! }))}
              />
              <IonInput
                fill="outline"
                label="Email"
                labelPlacement="floating"
                type="email"
                value={currentSupplier?.email}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => setCurrentSupplier(p => ({ ...p, email: e.detail.value! }))}
              />
              <IonTextarea
                fill="outline"
                label="Dirección"
                labelPlacement="floating"
                value={currentSupplier?.address}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => setCurrentSupplier(p => ({ ...p, address: e.detail.value! }))}
