              />
              <IonItem lines="none" className="ion-no-padding">
                <IonToggle
                  checked={currentSupplier?.active === '1'}
                  onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => setCurrentSupplier(p => ({ ...p, active: e.detail.checked ? '1' : '0' }))}
                >
                  <IonLabel>Activo</IonLabel>
                </IonToggle>
              </IonItem>
            </div>
            <IonButton expand="block" onClick={handleSaveSupplier} disabled={saving || !currentSupplier?.supplierName} className="ion-margin-top">
              {saving ? <IonIcon icon={checkmarkCircleOutline} slot="start" /> : <IonIcon icon={checkmarkCircleOutline} slot="start" />}
              {saving ? 'Guardando...' : 'Guardar'}
            </IonButton>
          </IonContent>
        </IonModal>

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={'¿Estás seguro de que quieres eliminar este proveedor?'}
          buttons={[
            { text: 'Cancelar', role: 'cancel' },
